<script lang="ts">
 import Icon from './Icon.svelte';
 let {rows,columns,t,lang='de',timezone='Europe/Berlin',collection='',model={}}:{lang?:string;timezone?:string;collection?:string;rows:Record<string,any>[];columns:string[];t:(key:string)=>string;model?:Record<string,any[]>}=$props();
 let extra=$state<Record<string,any>[]>([]),filter=$state(''),busy=$state(false),done=$state(false),message=$state(''),sort=$state(''),descending=$state(false),current=$state(0),size=$state(10),expanded=$state<Record<string,boolean>>({});
 let all=$derived([...rows,...extra]);
 const numeric=(key:string)=>/(?:_l|_ha|_kg|_ml)$/.test(key)||['cost_per_l','value','percentage','amount','actual_cost','planned_cost','allocated_cost','cost_per_unit','available','total_actual','total_planned','base_wine_cost','actual_per_l','actual_per_bottle','bottle_count','version','score','aroma','balance','vintage','planted_year','revision'].includes(key);
 const references:Record<string,string>={lot_id:'lots',parent_lot_id:'lots',child_lot_id:'lots',vessel_id:'vessels',target_vessel_id:'vessels',vineyard_id:'vineyards',resource_id:'resources',project_id:'projects',recipe_id:'recipes',trial_id:'trials',bottling_id:'bottlings',cost_id:'costs',user_id:'members',evaluator_id:'members',assignee_id:'members'};
 function reference(v:any,key:string){const list=model[references[key]];const row=list?.find(r=>r.id===v||r.user_id===v);return row?row.name??row.title??row.code??row.blind_code??t('uxDetails'):null;}
 function value(v:any,key:string):string{if(typeof v==='boolean')return t(v?'yes':'no');if(v===null||v===undefined)return '—';if(typeof v==='object')return Array.isArray(v)?v.map(item=>typeof item==='object'?(item.label??item.message??item.reason??t(item.rule??item.parameter??'uxDetails')):reference(item,'lot_id')??String(item)).join(' · '):Object.entries(v).map(([k,val])=>t(k)+': '+String(val??'—')).join(' · ');const ref=reference(v,key);if(ref)return ref;const text=String(v);if(numeric(key)&&Number.isFinite(Number(text)))return new Intl.NumberFormat(lang,{useGrouping:!['vintage','planted_year','version','revision','row'].includes(key),maximumFractionDigits:key.includes('cost')||key==='amount'?2:key==='value'?6:key==='area_ha'?4:3}).format(Number(text));if(/^\d{4}-\d{2}-\d{2}T\d{2}:/.test(text))return new Intl.DateTimeFormat(lang,{dateStyle:'short',timeStyle:'short',timeZone:timezone}).format(new Date(text));if(key==='status'&&text==='missing')return t('uxMissing');if(/^[a-f\d]{8}-[a-f\d-]{27}$/i.test(text))return text.slice(0,8);return text==='ph'?'pH':key==='kind'&&text==='bottle'?t('bottle_item'):t(text);}
 let visible=$derived.by(()=>{const filtered=all.filter(r=>!filter||columns.some(k=>value(r[k],k).toLocaleLowerCase().includes(filter.toLocaleLowerCase())));if(!sort)return filtered;return filtered.toSorted((a,b)=>{if(a[sort]==null)return 1;if(b[sort]==null)return -1;const compare=numeric(sort)?Number(a[sort])-Number(b[sort]):String(a[sort]).localeCompare(String(b[sort]),lang,{numeric:true});return descending?-compare:compare;});});
 let pages=$derived(Math.max(1,Math.ceil(visible.length/size))),slice=$derived(visible.slice(current*size,(current+1)*size));
 $effect(()=>{void rows;extra=[];done=false;});$effect(()=>{void filter;void size;void sort;void descending;current=0;});$effect(()=>{if(current>=pages)current=pages-1;});
 async function more(){busy=true;try{const res=await fetch('/api/read?collection='+encodeURIComponent(collection)+'&limit=500&cursor='+btoa(String(all.length)).replaceAll('=',''));const result=await res.json();if(res.ok){extra=[...extra,...result.rows];done=!result.next_cursor;}else message=t(result.message);}catch{message=t('CONNECTION_FAILED');}finally{busy=false;}}
 const tone=(v:any)=>['done','completed','ready','active','passed','within_range','committed','succeeded'].includes(v)?'good':['blocked','failed','outside_range','conflict'].includes(v)?'bad':['planned','doing','draft','open','pending','stale','missing','unknown','incompatible'].includes(v)?'warning':'info';
 const status=(key:string)=>['status','state','outcome','result','blocked','quality'].includes(key);
</script>
{#if all.length}<div class="table-toolbar"><label class="table-search"><span class="sr-only">{t('filterTable')} {t(collection)}</span><Icon name="search" size={17}/><input type="search" bind:value={filter} placeholder={t('filterTable')} /></label><span class="count">{visible.length} / {all.length}</span></div>{#if visible.length}<!-- svelte-ignore a11y_no_noninteractive_tabindex (Scrollable tables need keyboard focus.) --><div class="scroll" tabindex="0" role="region" aria-label={t(collection||'uxRecords')}><table><thead><tr>{#each columns as key}<th class:number={numeric(key)} aria-sort={sort===key?(descending?'descending':'ascending'):'none'}><button class="sort" onclick={()=>{if(sort===key)descending=!descending;else{sort=key;descending=false;}}}>{t(key==='user_id'?'uxTeamMember':key==='evaluator_id'?'uxEvaluator':key)}<span aria-hidden="true">{sort===key?(descending?'↓':'↑'):'↕'}</span></button></th>{/each}</tr></thead><tbody>{#each slice as row,i}<tr>{#each columns as key}<td class:number={numeric(key)} title={String(row[key]??'')}>{#if status(key)}<span class={'pill '+(typeof row[key]==='boolean'?(row[key]?'bad':'good'):tone(row[key]))}>{value(row[key],key)}</span>{:else if typeof row[key]==='object'&&row[key]!==null}<details><summary>{t('uxDetails')}{Array.isArray(row[key])?' ('+row[key].length+')':''}</summary><p>{value(row[key],key)}</p></details>{:else if value(row[key],key).length>100}<button class="text-detail" aria-expanded={!!expanded[i+'-'+key]} onclick={()=>expanded[i+'-'+key]=!expanded[i+'-'+key]}>{expanded[i+'-'+key]?value(row[key],key):value(row[key],key).slice(0,90)+'…'}</button>{:else}{value(row[key],key)}{/if}</td>{/each}</tr>{/each}</tbody></table></div><div class="pagination"><label>{t('uxRows')}<select bind:value={size}>{#each [10,25,50] as count}<option value={count}>{count}</option>{/each}</select></label><span>{current*size+1}–{Math.min((current+1)*size,visible.length)} / {visible.length}</span><div><button class="secondary" aria-label={t('uxPrevious')} disabled={current===0} onclick={()=>current--}>←</button><button class="secondary" aria-label={t('uxNext')} disabled={current>=pages-1} onclick={()=>current++}>→</button></div></div>{:else}<div class="empty-state"><p>{t('uxNoResults')}</p><button class="secondary" onclick={()=>filter=''}>{t('uxClear')}</button></div>{/if}{#if collection&&rows.length===500&&!done}<button class="secondary" onclick={more} disabled={busy}>{t('loadMore')}</button>{/if}{:else}<p class="empty-state">{t('uxEmptyHint')}</p>{/if}{#if message}<p class="notice" role="status">{message}</p>{/if}
<style>.table-toolbar{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-bottom:16px}.table-search{display:flex;align-items:center;position:relative;width:min(320px,100%)}.table-search :global(svg){position:absolute;left:12px;color:var(--muted)}.table-search input{padding-left:38px;min-height:39px;font-size:12px;background:#fafcfb}.count{font-size:11px;color:var(--muted);white-space:nowrap}.scroll{overflow:auto;max-width:100%;border:1px solid var(--line);border-radius:9px}table{border-collapse:collapse;width:100%;font-size:12px;text-align:left}th{background:#f6f9f7;white-space:nowrap;border-bottom:1px solid var(--line)}th .sort{display:flex;align-items:center;gap:14px;padding:12px 14px;background:transparent;color:#5f7368;font-size:11px;font-weight:600;min-height:43px;border:0;width:100%;text-align:left}th .sort span{font-size:12px;opacity:.65}td{padding:13px 14px;border-bottom:1px solid #edf2ee;max-width:330px;min-width:100px;line-height:1.6}tbody tr:last-child td{border:0}tbody tr:nth-child(even){background:#fcfdfc}tbody tr:hover{background:#f0f7f2}.number{text-align:right;font-variant-numeric:tabular-nums;white-space:nowrap}th.number .sort{justify-content:flex-end}.text-detail{font-size:12px;color:var(--ink);font-weight:400;background:none;padding:0;min-height:0;text-align:left;line-height:1.6}.text-detail:hover{color:var(--brand)}td details summary{font-size:11px;min-height:0;padding:0}td details p{white-space:normal;max-width:280px;color:var(--muted)}.pagination{display:flex;align-items:center;justify-content:space-between;gap:14px;margin:14px 0 0;font-size:11px;color:var(--muted)}.pagination label{display:flex;align-items:center;gap:10px;font-size:11px}.pagination select{width:65px;min-height:34px;font-size:11px;padding:5px 9px}.pagination>div{display:flex;gap:6px}.pagination button{width:38px;min-height:38px;padding:6px}@media(max-width:600px){.pagination{flex-wrap:wrap}.pagination label{font-size:10px}td,th .sort{padding:11px 12px}table{font-size:11px}}</style>
